"""Reproduction tests for count_zeros.py, generated by Debug GYM."""

from count_zeros import count_zeros


def test_no_zeros() -> None:
    assert count_zeros([1, 2, 3]) == 0


def test_zero_first() -> None:
    assert count_zeros([0, 1, 0]) == 2


def test_only_zeros() -> None:
    assert count_zeros([0, 0]) == 2
